SELECT game_id AS "gameId", ability_id AS "abilityId", state_key AS "stateKey", value_type_id AS "valueTypeId", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.ability_state_fields WHERE game_id = #{gameId}
AND ability_id = #{abilityId}
ORDER BY ability_id, state_key
